"""Selective header-compression engine: replay audit plus exact admission planning.

Reads one JSON request per stdin line and writes one JSON response per line.
Requests are independent.  See PROTOCOL.md for the byte format and semantics.
"""
import json
import re
import sys

MAX_LINE = 16 * 1024 * 1024
PACKET_BUDGET = 2 * 1024 * 1024
MAX_EVENTS = 20000
MAX_LABEL = 1048575
MIN_LABEL = 16
MAX_COUNT = 10 ** 9
HEADER_BYTE_BUDGET = 65536

ID_RE = re.compile(r'[A-Za-z0-9_.-]{1,32}')
REPLAY_KEYS = frozenset(('mode', 'capacities', 'flows', 'events'))
PLAN_KEYS = frozenset(('mode', 'capacities', 'flows', 'warmup', 'pinned', 'offers'))
REPLAY_FLOW_KEYS = frozenset(('id', 'path', 'template', 'kinds', 'labels'))
PLAN_FLOW_KEYS = frozenset(('id', 'path', 'template', 'kinds'))
RUN_KEYS = frozenset(('header', 'count'))
EVENT_FIELDS = {
    'put': frozenset(('flow', 'node')),
    'enable': frozenset(('flow',)),
    'disable': frozenset(('flow',)),
    'reset': frozenset(),
    'packet': frozenset(('flow', 'header', 'payload')),
}
EVENT_FULL = {op: keys | frozenset(('op',)) for op, keys in EVENT_FIELDS.items()}
MEMO_CAP = 300000


class Bad(Exception):
    """Any malformed JSON or schema violation."""


# --------------------------------------------------------------------------- helpers

def _pairs(pairs):
    out = {}
    for key, value in pairs:
        if key in out:
            raise Bad('duplicate key')
        out[key] = value
    return out


def as_int(value, low, high):
    if type(value) is not int:
        raise Bad('not int')
    if value < low or value > high:
        raise Bad('int range')
    return value


def as_id(value):
    if type(value) is not str or ID_RE.fullmatch(value) is None:
        raise Bad('id')
    return value


def as_hex(value, allow_empty=False):
    if type(value) is not str or len(value) % 2:
        raise Bad('hex')
    if not value:
        if allow_empty:
            return b''
        raise Bad('empty hex')
    try:
        raw = bytes.fromhex(value)
    except ValueError:
        raise Bad('hex digits')
    if raw.hex() != value:
        raise Bad('hex case')
    return raw


# --------------------------------------------------------------------------- parsing

def parse_capacities(spec):
    if type(spec) is not dict:
        raise Bad('capacities')
    if not 1 <= len(spec) <= 64:
        raise Bad('capacities size')
    caps = {}
    for key, value in spec.items():
        caps[as_id(key)] = as_int(value, 0, 512)
    return caps


def build_flow(fid, path, template, kinds, labels):
    size = len(template)
    kmask = bytearray(size)
    kval = bytearray(size)
    d_offs = []
    z_offs = []
    q_off = kinds.index('Q')
    t_off = kinds.index('T')
    for pos, kind in enumerate(kinds):
        if kind == 'K':
            kmask[pos] = 0xFF
            kval[pos] = template[pos]
        elif kind == 'D':
            d_offs.append(pos)
        elif kind == 'Z':
            z_offs.append(pos)
    base = bytearray(template)
    for pos in z_offs:
        base[pos] = 0
    flow = {
        'id': fid,
        'path': path,
        'N': len(path),
        'H': size,
        'nd': len(d_offs),
        'kmask': int.from_bytes(bytes(kmask), 'big'),
        'kval': int.from_bytes(bytes(kval), 'big'),
        'd_offs': d_offs,
        'q_off': q_off,
        't_off': t_off,
        'base': bytes(base),
    }
    if labels is not None:
        flow['labels'] = labels
        flow['label_of'] = dict(zip(path, labels))
    return flow


def parse_flows(spec, caps, replay):
    if type(spec) is not list:
        raise Bad('flows')
    limit = 512 if replay else 22
    if len(spec) > limit:
        raise Bad('flow count')
    want = REPLAY_FLOW_KEYS if replay else PLAN_FLOW_KEYS
    flows = {}
    for item in spec:
        if type(item) is not dict:
            raise Bad('flow')
        if set(item.keys()) != want:
            raise Bad('flow keys')
        fid = as_id(item['id'])
        if fid in flows:
            raise Bad('duplicate flow')
        raw_path = item['path']
        if type(raw_path) is not list or not 2 <= len(raw_path) <= 9:
            raise Bad('path')
        path = []
        for name in raw_path:
            node = as_id(name)
            if node not in caps:
                raise Bad('unknown node')
            if node in path:
                raise Bad('path duplicate')
            path.append(node)
        template = as_hex(item['template'])
        size = len(template)
        if not 8 <= size <= 256:
            raise Bad('template size')
        kinds = item['kinds']
        if type(kinds) is not str or len(kinds) != size:
            raise Bad('kinds')
        nk = kinds.count('K')
        nd = kinds.count('D')
        nz = kinds.count('Z')
        if nk + nd + nz + 2 != size:
            raise Bad('kinds alphabet')
        if kinds.count('Q') != 1 or kinds.count('T') != 1:
            raise Bad('kinds single')
        if nk < 1:
            raise Bad('no K byte')
        if 4 + nd >= size:
            raise Bad('too many D bytes')
        labels = None
        if replay:
            raw_labels = item['labels']
            if type(raw_labels) is not list or len(raw_labels) != len(path):
                raise Bad('labels')
            labels = [as_int(value, MIN_LABEL, MAX_LABEL) for value in raw_labels]
        flows[fid] = build_flow(fid, path, template, kinds, labels)
    return flows


def parse_events(spec, flows):
    if type(spec) is not list or len(spec) > MAX_EVENTS:
        raise Bad('events')
    out = []
    total = 0
    for event in spec:
        if type(event) is not dict:
            raise Bad('event')
        op = event.get('op')
        if type(op) is not str:
            raise Bad('op')
        fields = EVENT_FIELDS.get(op)
        if fields is None:
            raise Bad('op unknown')
        if set(event.keys()) != EVENT_FULL[op]:
            raise Bad('event keys')
        fid = as_id(event['flow'])
        flow = flows.get(fid)
        if flow is None:
            raise Bad('unknown flow')
        if op == 'put':
            node = as_id(event['node'])
            if node not in flow['label_of']:
                raise Bad('node off path')
            out.append(('put', fid, node))
        elif op == 'packet':
            header = as_hex(event['header'])
            if len(header) != flow['H']:
                raise Bad('header size')
            payload = as_hex(event['payload'], True)
            if len(payload) > 2048:
                raise Bad('payload size')
            total += len(header) + len(payload)
            if total > PACKET_BUDGET:
                raise Bad('packet budget')
            out.append(('packet', fid, header, payload))
        elif op == 'enable':
            out.append(('enable', fid))
        elif op == 'disable':
            out.append(('disable', fid))
        else:
            out.append(('reset',))
    return out


def parse_pinned(spec, flows):
    if type(spec) is not list:
        raise Bad('pinned')
    out = []
    seen = set()
    for value in spec:
        fid = as_id(value)
        if fid not in flows:
            raise Bad('pinned unknown')
        if fid in seen:
            raise Bad('pinned duplicate')
        seen.add(fid)
        out.append(fid)
    return out


def parse_offers(spec, flows):
    if type(spec) is not dict:
        raise Bad('offers')
    if set(spec.keys()) != set(flows.keys()):
        raise Bad('offers keys')
    out = {}
    total_bytes = 0
    for fid, runs in spec.items():
        if type(runs) is not list or len(runs) > 256:
            raise Bad('runs')
        flow = flows[fid]
        size = flow['H']
        parsed = []
        run_total = 0
        for run in runs:
            if type(run) is not dict or set(run.keys()) != RUN_KEYS:
                raise Bad('run keys')
            header = as_hex(run['header'])
            if len(header) != size:
                raise Bad('run header size')
            count = as_int(run['count'], 1, MAX_COUNT)
            run_total += count
            if run_total > MAX_COUNT:
                raise Bad('run total')
            total_bytes += size
            if total_bytes > HEADER_BYTE_BUDGET:
                raise Bad('header bytes')
            parsed.append((header, count))
        out[fid] = parsed
    return out


def parse_request(req):
    if type(req) is not dict:
        raise Bad('request')
    mode = req.get('mode')
    if type(mode) is not str:
        raise Bad('mode')
    if mode == 'replay':
        if set(req.keys()) != REPLAY_KEYS:
            raise Bad('replay keys')
        caps = parse_capacities(req['capacities'])
        flows = parse_flows(req['flows'], caps, True)
        events = parse_events(req['events'], flows)
        return run_replay(caps, flows, events)
    if mode == 'plan':
        if set(req.keys()) != PLAN_KEYS:
            raise Bad('plan keys')
        caps = parse_capacities(req['capacities'])
        flows = parse_flows(req['flows'], caps, False)
        warmup = as_int(req['warmup'], 0, MAX_COUNT)
        pinned = parse_pinned(req['pinned'], flows)
        offers = parse_offers(req['offers'], flows)
        return run_plan(caps, flows, warmup, pinned, offers)
    raise Bad('mode unknown')


# --------------------------------------------------------------------------- replay

def run_replay(caps, flows, events):
    tables = {}
    node_count = {}
    enabled = set()
    results = []
    append = results.append
    for event in events:
        op = event[0]
        if op == 'packet':
            fid = event[1]
            flow = flows[fid]
            header = event[2]
            payload = event[3]
            size = flow['H']
            nodes = flow['N']
            if fid not in enabled:
                reason = 'disabled'
            elif (int.from_bytes(header, 'big') & flow['kmask']) != flow['kval']:
                reason = 'mismatch'
            elif header[flow['q_off']] > 7:
                reason = 'qos'
            else:
                reason = ''
            ttl = header[flow['t_off']]
            emitted = nodes if ttl >= nodes else ttl
            if reason:
                offset = flow['t_off']
                prefix = bytes(header[:offset])
                suffix = bytes(header[offset + 1:])
                wire = []
                for hop in range(emitted):
                    wire.append((prefix + (ttl - hop).to_bytes(1, 'big') + suffix
                                 + payload).hex())
                delivered = wire[-1] if emitted == nodes else None
                append({'mode': 'ip', 'reason': reason, 'wire': wire,
                        'delivered': delivered,
                        'byte_hops': emitted * (size + len(payload))})
                continue
            qos = header[flow['q_off']]
            d_offs = flow['d_offs']
            residue = bytes([header[pos] for pos in d_offs])
            labels = flow['labels']
            wire = []
            for hop in range(emitted):
                word = ((labels[hop] << 12) | (qos << 9) | 256 | (ttl - hop))
                wire.append((word.to_bytes(4, 'big') + residue + payload).hex())
            if emitted == nodes:
                out = bytearray(flow['base'])
                for pos in range(len(d_offs)):
                    out[d_offs[pos]] = residue[pos]
                out[flow['q_off']] = qos
                out[flow['t_off']] = ttl - nodes + 1
                delivered = (bytes(out) + payload).hex()
            else:
                delivered = None
            append({'mode': 'mpls', 'reason': 'compressed', 'wire': wire,
                    'delivered': delivered,
                    'byte_hops': emitted * (4 + len(residue) + len(payload))})
            continue
        fid = event[1]
        if op == 'put':
            flow = flows[fid]
            node = event[2]
            label = flow['label_of'][node]
            key = (node, label)
            current = tables.get(key)
            if current == fid:
                append({'status': 'ok'})
            elif current is not None and current in enabled:
                append({'status': 'busy'})
            elif current is None and node_count.get(node, 0) >= caps[node]:
                append({'status': 'full'})
            else:
                if current is None:
                    node_count[node] = node_count.get(node, 0) + 1
                tables[key] = fid
                append({'status': 'ok'})
        elif op == 'enable':
            flow = flows[fid]
            for node in flow['path']:
                if tables.get((node, flow['label_of'][node])) != fid:
                    append({'status': 'unready'})
                    break
            else:
                enabled.add(fid)
                append({'status': 'ok'})
        elif op == 'disable':
            enabled.discard(fid)
            append({'status': 'ok'})
        else:
            enabled.clear()
            append({'status': 'ok'})
    listing = [{'node': node, 'label': label, 'flow': holder}
               for (node, label), holder in sorted(tables.items())]
    return {'results': results, 'active': sorted(enabled), 'tables': listing}


# --------------------------------------------------------------------------- planning

def solve_component(items, rem):
    """Exact optimum for one independent component.

    items: list of (benefit, nodes tuple, flow id).  rem: node -> free slots.
    Returns (benefit, count, bitmask over items).
    """
    count_items = len(items)
    groups = {}
    for benefit, nodes, _fid in items:
        bucket = groups.get(nodes)
        if bucket is None:
            groups[nodes] = [(benefit, 0)]
        else:
            bucket.append((benefit, 0))
    glist = []
    for nodes, bucket in groups.items():
        bucket.sort(key=lambda entry: -entry[0])
        pre = [0]
        masks = [0]
        for position, (benefit, _idx) in enumerate(bucket):
            pre.append(pre[-1] + benefit)
            masks.append(masks[-1] | (1 << position))
        glist.append([nodes, pre, masks, len(bucket)])
    if not glist:
        return 0, 0, 0
    # Order groups by top benefit (good incumbents early), then index nodes so
    # that shared nodes get nearby indices, then reorder for state locality.
    glist.sort(key=lambda group: (-group[1][1], group[0]))
    node_index = {}
    for group in glist:
        for node in group[0]:
            if node not in node_index:
                node_index[node] = len(node_index)
    node_names = [None] * len(node_index)
    for name, index in node_index.items():
        node_names[index] = name
    slots = [rem[name] for name in node_names]
    for group in glist:
        group[0] = tuple(sorted(node_index[node] for node in group[0]))
    glist.sort(key=lambda group: (group[0][-1], -group[1][1]))
    ngroups = len(glist)

    # suffix benefit sums
    suf = [0] * (ngroups + 1)
    for i in range(ngroups - 1, -1, -1):
        size = glist[i][3]
        suf[i] = suf[i + 1] + glist[i][1][size]

    # per node, per level: count, total, and prefix sums of sorted benefits
    per_node = [[] for _ in slots]
    for level, group in enumerate(glist):
        nodes, pre = group[0], group[1]
        for position in range(group[3]):
            benefit = pre[position + 1] - pre[position]
            for node in nodes:
                per_node[node].append((level, benefit))
    U_at = [None] * len(slots)
    cnt_at = [None] * len(slots)
    tsum_at = [None] * len(slots)
    for node in range(len(slots)):
        entries = per_node[node]
        buckets = [[] for _ in range(ngroups)]
        for level, benefit in entries:
            buckets[level].append(benefit)
        Uarr = [None] * (ngroups + 1)
        carr = [0] * (ngroups + 1)
        tarr = [0] * (ngroups + 1)
        cur = []
        total = 0
        Uarr[ngroups] = (0,)
        for level in range(ngroups - 1, -1, -1):
            if buckets[level]:
                cur.extend(buckets[level])
                cur.sort(reverse=True)
                total = 0
                prefix = [0]
                for value in cur:
                    total += value
                    prefix.append(total)
                Uarr[level] = tuple(prefix)
            else:
                Uarr[level] = Uarr[level + 1]
            carr[level] = len(cur)
            tarr[level] = total
        U_at[node] = Uarr
        cnt_at[node] = carr
        tsum_at[node] = tarr

    # active node sets per level
    last_level = [-1] * len(slots)
    for level, group in enumerate(glist):
        for node in group[0]:
            last_level[node] = level
    active = []
    for level in range(ngroups + 1):
        active.append(tuple(node for node in range(len(slots))
                            if last_level[node] >= level))

    best = [0, 0, 0]
    memo = {}
    used = [0] * len(slots)

    def rec(level, acc_b, acc_c, mask):
        if level == ngroups:
            if acc_b > best[0] or (acc_b == best[0] and acc_c < best[1]):
                best[0] = acc_b
                best[1] = acc_c
                best[2] = mask
            return 0, 0, True
        nodes_here = active[level]
        if nodes_here:
            key = (level, tuple([used[node] for node in nodes_here]))
        else:
            key = (level, ())
        hit = memo.get(key)
        if hit is not None:
            return hit[0], hit[1], True
        limit = suf[level]
        for node in nodes_here:
            avail = slots[node] - used[node]
            total = tsum_at[node][level]
            if avail <= 0:
                bound = limit - total
            else:
                cnt = cnt_at[node][level]
                table = U_at[node][level]
                pick = avail if avail < cnt else cnt
                bound = table[pick] + limit - total
            if bound < limit:
                limit = bound
            if limit <= 0:
                break
        if acc_b + limit < best[0] or (acc_b + limit == best[0] and acc_c >= best[1]):
            return 0, 0, False
        nodes, pre, masks, size = glist[level]
        cap = size
        for node in nodes:
            avail = slots[node] - used[node]
            if avail < cap:
                cap = avail
        best_value = None
        exact = True
        for take in range(cap, -1, -1):
            if take:
                for node in nodes:
                    used[node] += take
            got_b, got_c, got_exact = rec(level + 1, acc_b + pre[take],
                                          acc_c + take, mask | masks[take])
            if take:
                for node in nodes:
                    used[node] -= take
            if not got_exact:
                exact = False
            value = (got_b + pre[take], -(got_c + take))
            if best_value is None or value > best_value:
                best_value = value
        if exact and len(memo) < MEMO_CAP:
            memo[key] = best_value
        return best_value[0], -best_value[1], exact

    rec(0, 0, 0, 0)
    return best[0], best[1], best[2]


def run_plan(caps, flows, warmup, pinned, offers):
    benefit = {}
    for fid, flow in flows.items():
        nodes = flow['N']
        hops = nodes - 1
        per_packet = (flow['H'] - 4 - flow['nd']) * nodes
        kmask = flow['kmask']
        kval = flow['kval']
        q_off = flow['q_off']
        t_off = flow['t_off']
        total = 0
        index = 0
        for header, count in offers[fid]:
            end = index + count
            if end > warmup:
                start = index if index > warmup else warmup
                eligible = end - start
                if ((int.from_bytes(header, 'big') & kmask) != kval
                        or header[q_off] > 7 or header[t_off] <= hops):
                    eligible = 0
                total += per_packet * eligible
            index = end
        benefit[fid] = total

    pinned_set = set(pinned)
    pin_usage = {}
    for fid in pinned:
        for node in flows[fid]['path']:
            pin_usage[node] = pin_usage.get(node, 0) + 1
    for node, used in pin_usage.items():
        if used > caps[node]:
            return {'infeasible': True}
    base_benefit = sum(benefit[fid] for fid in pinned)
    slots = {node: caps[node] - pin_usage.get(node, 0) for node in caps}

    candidates = []
    for fid, flow in flows.items():
        if fid in pinned_set:
            continue
        if benefit[fid] <= 0:
            continue
        ok = True
        for node in flow['path']:
            if slots[node] <= 0:
                ok = False
                break
        if ok:
            candidates.append(fid)

    through = {}
    for fid in candidates:
        for node in flows[fid]['path']:
            through[node] = through.get(node, 0) + 1
    binding = set()
    for node, cnt in through.items():
        if cnt > slots[node]:
            binding.add(node)

    free_benefit = 0
    chosen = []
    grouped = []
    for fid in candidates:
        hot = tuple(node for node in flows[fid]['path'] if node in binding)
        if hot:
            grouped.append((benefit[fid], hot, fid))
        else:
            free_benefit += benefit[fid]
            chosen.append(fid)

    parent = {node: node for node in binding}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    for _benefit, nodes, _fid in grouped:
        root = find(nodes[0])
        for node in nodes[1:]:
            other = find(node)
            if other != root:
                parent[other] = root
    components = {}
    for entry in grouped:
        components.setdefault(find(entry[1][0]), []).append(entry)

    for items in components.values():
        local = {}
        for _benefit, nodes, _fid in items:
            for node in nodes:
                local[node] = slots[node]
        gain, _count, mask = solve_component(items, local)
        free_benefit += gain
        for position, (_benefit, _nodes, fid) in enumerate(items):
            if (mask >> position) & 1:
                chosen.append(fid)

    chosen.extend(pinned)
    selected = sorted(set(chosen))
    saved = sum(benefit[fid] for fid in selected)
    return {'selected': selected, 'saved': saved}


# --------------------------------------------------------------------------- driver

def main():
    out = sys.stdout
    for raw in sys.stdin.buffer:
        if len(raw) > MAX_LINE:
            out.write('{"error":"input"}\n')
            out.flush()
            continue
        try:
            request = json.loads(raw.decode('utf-8'), object_pairs_hook=_pairs)
            response = parse_request(request)
        except Bad:
            response = {'error': 'input'}
        except (ValueError, TypeError, KeyError, IndexError, AttributeError,
                RecursionError, UnicodeDecodeError):
            response = {'error': 'input'}
        out.write(json.dumps(response, separators=(',', ':')))
        out.write('\n')
        out.flush()


if __name__ == '__main__':
    main()
